package basics;

public class BasicProgram {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		/*
		 
		 Datatypes are of 2 types:-
		 1.PRIMITIVE :- int,double,float,long,boolean,short
		 2.NON PRIMITIVE :- String, Arrays
		 
		 12.34
		 */
		
		int a=4,b=5; //initialization 
		
		int c,d; //declaration
		
		//ln line next
		//                  Addition    9
		System.out.println("Addition "+(a+b));
		
		System.out.println("Subtraction "+(a-b));
		
		System.out.println("Multiplication "+(a*b));
		
		System.out.println("Divison "+(a/b));
		
		//+ operator is used to join print statement with variable
		//+ operator is also used to join print statement with operations
		
		
		//double is datatype used for decimal numbers 
		double g=12, h=5;
		//12.333333333333333334
		System.out.println("Addition "+(g+h));
		
		//float 
		//12.334
		float k=4.5f, m=3.4f;
		
		System.out.println("Addition "+(k+m));
		
		
		
		
		
		
		
		
	}

}
